const ctx = JSON.parse(JSON.stringify($('Match PO').first().json));
const r = $input.first()?.json ?? {};
if (r.error) {
  ctx.status = 'PO_PRICE_UPDATE_FAILED';
  ctx.reason = `ServiceTitan PO update failed: ${typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error))}`;
} else {
  ctx.status = 'READY_TO_POST';
  ctx.payload = ctx.pending_payload;
  ctx.warnings.push(`PO ${ctx.st_po.number} priced in ServiceTitan from the invoice`);
}
delete ctx.pending_payload;
delete ctx.st_patch_body;
return [{ json: ctx }];

// Settings come from the summers.datastore.config.keys data table: { CATEGORY: { key: value } }.
const parse = v => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (/^(true|false)$/i.test(s)) return s.toLowerCase() === 'true';
  if (/^-?\d+(\.\d+)?$/.test(s)) return Number(s);
  if (/^[\[{]/.test(s)) { try { return JSON.parse(s); } catch (e) { /* keep as text */ } }
  return s;
};
const cfg = {};
for (const { json: r } of $input.all()) {
  if (!r || !r.category || !r.key) continue;
  (cfg[r.category] ||= {})[r.key] = parse(r.value);
}
// Fail loudly if a required setting is missing, rather than running with a guess.
const REQUIRED = ["GLOBAL_CONFIG.st_api_base", "GLOBAL_CONFIG.st_auth_url", "GLOBAL_CONFIG.extraction_endpoint", "GLOBAL_CONFIG.glm_extraction_model", "GLOBAL_CONFIG.glm_lines_max_tokens", "INV_PROC_CONFIG.validation_tolerance", "INV_PROC_CONFIG.line_price_tolerance", "INV_PROC_CONFIG.allow_st_price_update", "INV_PROC_CONFIG.vendor_match_stopwords"];
const missing = REQUIRED.filter(p => { const [c, k] = p.split('.'); const v = cfg[c]?.[k]; return v === undefined || v === null || v === ''; });
if (missing.length) throw new Error('Missing settings in summers.datastore.config.keys: ' + missing.join(', '));
return [{ json: { cfg } }];

// Pick exactly one ServiceTitan PO.
const ctx = JSON.parse(JSON.stringify($('Start').first().json));
const resp = $input.first()?.json ?? {};
const exc = (s, r) => { ctx.status = s; ctx.reason = r; return [{ json: ctx }]; };
if (resp.error) return exc('ST_API_ERROR', `ServiceTitan PO lookup failed: ${typeof resp.error === 'string' ? resp.error : (resp.error.message || JSON.stringify(resp.error))}`);

const list = Array.isArray(resp.data) ? resp.data : [];
const search = String(ctx.po.st_search_number || '').toUpperCase();
const exact = list.filter(p => String(p.number || '').toUpperCase() === search);
const pool = exact.length ? exact : list;
if (!pool.length) return exc('PO_NOT_FOUND', `PO ${ctx.po.raw} (searched ${search}) not found in ServiceTitan`);
if (pool.length > 1) return exc('PO_AMBIGUOUS', `${pool.length} ServiceTitan POs match ${search}: ${pool.map(p => p.number).join(', ')}`);
const po = pool[0];
if (/cancel/i.test(String(po.status || ''))) return exc('PO_CANCELED', `PO ${po.number} is ${po.status} in ServiceTitan`);
ctx.st_po = po;
return [{ json: ctx }];

const LEGAL_SUFFIXES = /\b(incorporated|llc|l\.l\.c|inc|corp|corporation|co|company|ltd|limited|llp|lp|enterprises?|facilit(?:y|ies)|industries|international|the)\b/g;
function normVendor(raw) {
  if (!raw) return '';
  return String(raw).toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[.,\/#!$%\^*;:{}=\-_`~()'"]/g, ' ')
    .replace(LEGAL_SUFFIXES, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Two-way match: vendor, location, quantity, total. Builds the Sage payload.
const I = $('Build Config').first().json.cfg.INV_PROC_CONFIG;
const CONFIG = {
  TOTAL_TOLERANCE: I.validation_tolerance,
  LINE_PRICE_TOLERANCE: I.line_price_tolerance,       // per-unit difference reported as a price variance
  ALLOW_ST_PRICE_UPDATE: I.allow_st_price_update === true,   // turn on only with 'ST Update PO Price'
    DEPT_COLS: { department: 'department_code', location: 'location_code' },
};
const ctx = JSON.parse(JSON.stringify($('Parse Lines').first().json));   // has the stage-2 line items
const po = ctx.st_po;
const inv = ctx.invoice;
const round2 = n => Math.round(n * 100) / 100;
const key = s => String(s ?? '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
const exc = (s, r) => { ctx.status = s; ctx.reason = r; return [{ json: ctx }]; };

const vendorResp = $('ST Get Vendor').first()?.json ?? {};
const deptRow = $input.all().map(i => i.json).find(r => r && Object.keys(r).length && !r.error) || null;
const checks = {};

// Vendor
const stVendorName = vendorResp.error ? null : (vendorResp.name ?? vendorResp.data?.name ?? null);
if (!stVendorName) {
  checks.vendor = { result: 'SKIPPED', detail: 'ServiceTitan vendor name unavailable' };
} else if (!ctx.vendor?.name) {
  // Some invoices print no vendor name (logo only); the PO's vendor is the authoritative one.
  ctx.vendor = { ...(ctx.vendor || {}), name: stVendorName };
  checks.vendor = { result: 'PASS', detail: `Vendor name not printed on invoice; using ServiceTitan PO vendor "${stVendorName}"` };
  (ctx.warnings ||= []).push(checks.vendor.detail);
} else {
  const a = normVendor(stVendorName), b = normVendor(ctx.vendor?.name);
  // Exact/contained names pass; otherwise every word of the shorter name must appear in the longer one
  // (handles "Johnstone Supply Indianapolis West" vs "Johnstone Indianapolis West").
  const STOP = new Set((I.vendor_match_stopwords || []).map(w => String(w).toLowerCase()));
  const words = s => s.split(' ').filter(w => w.length > 1 && !STOP.has(w));
  const [sw, lw] = words(a).length <= words(b).length ? [words(a), new Set(words(b))] : [words(b), new Set(words(a))];
  const exact = a && b && (a === b || a.includes(b) || b.includes(a));
  const fuzzy = !exact && sw.length > 0 && sw.every(w => lw.has(w));
  checks.vendor = { result: exact || fuzzy ? 'PASS' : 'FAIL',
                    detail: `ServiceTitan "${stVendorName}" vs invoice "${ctx.vendor?.name}"${fuzzy ? ' (word match)' : ''}` };
}

// Location: PO business unit's location vs resolved invoice location
const deptLoc = deptRow ? String(deptRow[CONFIG.DEPT_COLS.location] ?? '').trim().toUpperCase() : '';
checks.location = deptLoc
  ? { result: deptLoc === ctx.location.code ? 'PASS' : 'FAIL', detail: `PO business unit ${po.businessUnitId} is ${deptLoc}; invoice resolved to ${ctx.location.code}` }
  : { result: 'SKIPPED', detail: 'No location code for this business unit in the Department Code sheet' };

const department = deptRow ? (String(deptRow[CONFIG.DEPT_COLS.department] ?? '').trim() || null) : null;
if (!department) ctx.warnings.push(`No department code for business unit ${po.businessUnitId}`);

// Quantity: invoiced must not exceed ordered (partial shipments are fine)
const poItems = Array.isArray(po.items) ? po.items : [];
const lineFor = it => (inv.line_items || []).find(l => key(l.sku) && [it.vendorPartNumber, it.skuCode, it.skuName].some(v => key(v) === key(l.sku)));
const qtyIssues = [];
for (const it of poItems) {
  const l = lineFor(it);
  if (l && l.quantity != null && it.quantity != null && Number(l.quantity) > Number(it.quantity)) qtyIssues.push(`${l.sku}: invoiced ${l.quantity} > PO ${it.quantity}`);
}
checks.quantity = qtyIssues.length ? { result: 'FAIL', detail: qtyIssues.join('; ') } : { result: 'PASS' };

// Total: gross or net (ex tax/freight) within tolerance
const tol = CONFIG.TOTAL_TOLERANCE;
const poTotal = Number(po.total ?? 0);
const invTotal = Number(inv.invoice_total ?? 0);
const invNet = inv.subtotal ?? round2(invTotal - (inv.tax ?? 0) - (inv.freight ?? 0));
const poNet = round2(poTotal - Number(po.tax ?? 0) - Number(po.shipping ?? 0));
checks.total = poTotal === 0
  ? { result: 'ZERO_PO', detail: 'PO has no price; will be updated from the invoice' }
  : { result: (Math.abs(poTotal - invTotal) <= tol || Math.abs(poNet - invNet) <= tol) ? 'PASS' : 'FAIL',
      detail: `PO ${poTotal} (net ${poNet}) vs invoice ${invTotal} (net ${invNet})` };
ctx.match_checks = checks;

// Line-level variance (for the Daily Report and the reviewer email)
const num = v => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v))) ? null : Number(v);
const used = new Set();
const variance = [];
for (const it of poItems) {
  const l = lineFor(it);
  if (l) used.add(l);
  const poQty = num(it.quantity), poUnit = num(it.cost);
  const invQty = l ? num(l.quantity) : null;
  const invUnit = l ? (num(l.unit_price) ?? (num(l.amount) !== null && invQty ? round2(l.amount / invQty) : null)) : null;
  const poExt = poQty !== null && poUnit !== null ? round2(poQty * poUnit) : null;
  const invExt = l ? (num(l.amount) ?? (invQty !== null && invUnit !== null ? round2(invQty * invUnit) : null)) : null;
  let st = 'OK';
  if (!l) st = 'NOT_INVOICED';
  else if (poUnit === 0) st = 'PO_UNPRICED';
  else if (invQty !== null && poQty !== null && invQty > poQty) st = 'QTY_OVER';
  else if (invUnit !== null && poUnit !== null && poUnit !== 0 && Math.abs(invUnit - poUnit) > CONFIG.LINE_PRICE_TOLERANCE) st = 'PRICE_DIFF';
  variance.push({ sku: l?.sku ?? it.vendorPartNumber ?? it.skuCode ?? it.skuName ?? null, description: it.description ?? it.skuName ?? l?.description ?? null,
                  po_qty: poQty, inv_qty: invQty, po_unit: poUnit, inv_unit: invUnit, po_ext: poExt, inv_ext: invExt,
                  diff: poExt !== null && invExt !== null ? round2(invExt - poExt) : null, status: st });
}
for (const l of (inv.line_items || [])) {
  if (used.has(l)) continue;
  variance.push({ sku: l.sku, description: l.description, po_qty: null, inv_qty: num(l.quantity), po_unit: null, inv_unit: num(l.unit_price),
                  po_ext: null, inv_ext: num(l.amount), diff: num(l.amount), status: 'NOT_ON_PO' });
}
ctx.variance_lines = variance;
ctx.variance_amount = poTotal === 0 ? null : round2(invTotal - poTotal);

// Hard failures first
const order = [['vendor', 'PO_VENDOR_MISMATCH'], ['location', 'PO_LOCATION_MISMATCH'], ['quantity', 'PO_QTY_MISMATCH'], ['total', 'PO_PRICE_MISMATCH']];
const failed = order.filter(([k]) => checks[k].result === 'FAIL');
if (failed.length) return exc(failed[0][1], failed.map(([k]) => `${k}: ${checks[k].detail}`).join(' | '));

// Sage payload (the dominant PO item drives the GL)
const sorted = [...poItems].sort((a, b) => (Number(b.quantity ?? 0) * Number(b.cost ?? 0)) - (Number(a.quantity ?? 0) * Number(a.cost ?? 0)));
const payload = {
  location_id: ctx.location.entity_id,
  line_location_id: ctx.location.sage_location_id || ctx.location.entity_id,
  vendor: { sage_vendor_id: null, name: ctx.vendor.name, location_code: ctx.location.code },
  bill: { record_id: inv.invoice_number, doc_number: po.number || ctx.po.normalized,
          when_created: inv.invoice_date, when_due: inv.due_date, term: inv.payment_terms,
          description: `${ctx.vendor.name} ${inv.invoice_number} / PO ${po.number}` },
  lines: [{ amount: invTotal, gl_account: null, item_names: [...new Set(sorted.map(it => it.skuName).filter(Boolean))],
            department, memo: `Invoice ${inv.invoice_number} / PO ${po.number}` }],
};

// Zero-priced PO: price it from the invoice, then post
if (poTotal === 0 && !CONFIG.ALLOW_ST_PRICE_UPDATE) {
  return exc('PO_PRICE_UPDATE_REVIEW', `PO ${po.number} has no prices in ServiceTitan; automatic price update is switched off`);
}
if (poTotal === 0) {
  const items = [];
  for (const it of poItems) {
    const l = lineFor(it);
    let cost = null;
    if (l) cost = l.unit_price ?? (l.amount != null && l.quantity ? l.amount / l.quantity : null);
    else if (poItems.length === 1 && Number(it.quantity)) cost = invNet / Number(it.quantity);
    if (cost === null) return exc('PO_PRICE_UPDATE_REVIEW', `Cannot price PO item ${it.skuName || it.id} from the invoice lines`);
    items.push({ id: it.id, skuId: it.skuId, description: it.description, vendorPartNumber: it.vendorPartNumber,
                 quantity: it.quantity, cost: Math.round(cost * 10000) / 10000, budgetCodeId: it.budgetCodeId ?? null });
  }
  if (!items.length) return exc('PO_PRICE_UPDATE_REVIEW', 'PO has no items to price');
  const s = po.shipTo || {};
  ctx.st_patch_body = {
    vendorId: po.vendorId, typeId: po.typeId, businessUnitId: po.businessUnitId, inventoryLocationId: po.inventoryLocationId,
    jobId: po.jobId, projectId: po.projectId, vendorInvoiceNumber: inv.invoice_number, memo: po.memo ?? '',
    date: po.date, requiredOn: po.requiredOn, tax: inv.tax ?? po.tax ?? 0, shipping: inv.freight ?? po.shipping ?? 0,
    shipTo: { description: s.description ?? '', address: { street: s.street ?? '', unit: s.unit ?? '', city: s.city ?? '', state: s.state ?? '', zip: s.zip ?? '', country: s.country ?? 'US' } },
    items,
  };
  ctx.pending_payload = payload;
  ctx.status = 'PRICE_UPDATE';
  return [{ json: ctx }];
}

ctx.status = 'READY_TO_POST';
ctx.payload = payload;
return [{ json: ctx }];

// Stage 2: parse the line items for this one invoice and attach them to the context.
const CONFIG = { REQUIRE_LINES: true };
const ctx = JSON.parse(JSON.stringify($('Evaluate PO').first().json));
ctx.warnings = ctx.warnings || [];
const TOL = $('Build Config').first().json.cfg.INV_PROC_CONFIG.validation_tolerance;
const resp = $input.first()?.json ?? {};
const round2 = n => Math.round(n * 100) / 100;

/*
 * Strict amount parser: accepts JSON numbers and printed amounts (1,234.56  -234.89  (234.89)  234.89-  $1,234.56).
 * Anything else is REJECTED (bad = true), never "cleaned up", so a corrupted token such as "-234.!89!!89"
 * can no longer become -234.8989.
 */
const AMOUNT_RE = /^(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?$|^\.\d+$/;
function parseAmount(v) {
  if (v === null || v === undefined || v === '') return { value: null, bad: false };
  if (typeof v === 'number') return Number.isFinite(v) ? { value: v, bad: false } : { value: null, bad: true };
  let s = String(v).trim(), neg = false;
  if (!s) return { value: null, bad: false };
  if (/^\(.*\)$/.test(s)) { neg = true; s = s.slice(1, -1).trim(); }
  if (/-$/.test(s)) { neg = true; s = s.slice(0, -1).trim(); }
  if (/^[-\u2212\u2013]/.test(s)) { neg = true; s = s.slice(1).trim(); }
  s = s.replace(/^[$\u20AC\u00A3]\s*/, '');
  if (!AMOUNT_RE.test(s)) return { value: null, bad: true };
  const n = Number(s.replace(/,/g, ''));
  return Number.isFinite(n) ? { value: neg ? -n : n, bad: false } : { value: null, bad: true };
}
function buildSrcCents(text) {
  const set = new Set();
  const add = s => { const n = Number(s); if (Number.isFinite(n)) set.add(Math.round(n * 100)); };
  for (const t of String(text).match(/\d[\d,]*(?:\.\d+)?|\.\d+/g) || []) {
    add(t.replace(/,/g, ''));
    // PDF text extraction can glue two numbers together (quantity 3 + price 149.99 -> 3149.99).
    // For a decimal token with no thousands separators and 4+ integer digits, also accept its trailing digit groups.
    const m = t.match(/^(\d{4,})(\.\d+)$/);
    if (m) for (let i = 1; i < m[1].length; i++) add(m[1].slice(i) + m[2]);
  }
  return set;
}
const srcCents = buildSrcCents(ctx.source_text || '');
let badAmounts = 0;
const num = v => { const r = parseAmount(v); if (r.bad) badAmounts++; return r.value; };
// Prices and amounts must also appear in the document text.
const amt = v => {
  const r = parseAmount(v);
  if (r.bad) { badAmounts++; return null; }
  if (r.value !== null && r.value !== 0 && !srcCents.has(Math.round(Math.abs(r.value) * 100))) badAmounts++;
  return r.value;
};
function parse(r) {
  if (!r || r.error) return { error: 'Line-item LLM request failed' + (r?.error ? ': ' + (r.error.message || JSON.stringify(r.error)) : '') };
  const ch = r.choices?.[0];
  if (ch?.finish_reason === 'length') return { error: 'Line-item output truncated (finish_reason=length); raise glm_lines_max_tokens' };
  if (ch?.finish_reason !== undefined && ch?.finish_reason !== null && ch.finish_reason !== 'stop') return { error: `Line-item LLM did not finish normally (finish_reason=${ch.finish_reason})` };
  const raw = ch?.message?.content;
  if (!raw) return { error: 'Line-item LLM returned empty content' };
  const cleaned = String(raw).replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  try { return { data: JSON.parse(cleaned) }; } catch (e) {
    const a = cleaned.indexOf('{'), b = cleaned.lastIndexOf('}');
    if (a >= 0 && b > a) { try { return { data: JSON.parse(cleaned.slice(a, b + 1)) }; } catch (e2) {} }
    return { error: 'Could not parse line-item JSON: ' + e.message };
  }
}
const p = parse(resp);
if (p.error) {
  ctx.line_count = 0;
  if (CONFIG.REQUIRE_LINES) { ctx.status = 'EXTRACTION_FAILED'; ctx.reason = p.error; }
  else ctx.warnings.push(p.error + ' (continuing without line items)');
  return [{ json: ctx }];
}
const lines = (Array.isArray(p.data?.line_items) ? p.data.line_items : [])
  .map(li => ({ sku: li?.sku ?? null, description: li?.description ?? null, quantity: num(li?.quantity), unit_price: amt(li?.unit_price), amount: amt(li?.amount) }))
  .filter(l => l.sku || l.description || l.amount !== null);
const inv = ctx.invoice;
if (badAmounts) {
  inv.line_items = [];
  ctx.line_count = 0;
  const msg = `${badAmounts} line amount(s) unreadable or not in the document; line items discarded`;
  if (CONFIG.REQUIRE_LINES) { ctx.status = 'EXTRACTION_FAILED'; ctx.reason = msg; }
  else ctx.warnings.push(msg);
  return [{ json: ctx }];
}
inv.line_items = lines;
ctx.line_count = lines.length;
for (const l of lines) {
  if (l.quantity !== null && l.unit_price !== null && l.amount !== null && Math.abs(round2(l.quantity * l.unit_price) - l.amount) > TOL)
    ctx.warnings.push(`Line ${l.sku ?? l.description}: qty x price != amount`);
}
const priced = lines.filter(l => l.amount !== null);
const lineSum = round2(priced.reduce((s, l) => s + l.amount, 0));
if (priced.length && inv.subtotal !== null && inv.subtotal !== undefined &&
    Math.abs(lineSum - inv.subtotal) > TOL && Math.abs(lineSum + (inv.freight ?? 0) - inv.subtotal) > TOL)
  ctx.warnings.push(`Line items sum ${lineSum} != subtotal ${inv.subtotal}`);
if (!lines.length) {
  if (CONFIG.REQUIRE_LINES) { ctx.status = 'EXTRACTION_FAILED'; ctx.reason = `No line items found for invoice ${inv.invoice_number}`; }
  else ctx.warnings.push('No line items found');
}
return [{ json: ctx }];
